local function __aerials_pack_b64_decode(__data)
    local __alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local __map = {}
    for __i = 1, #__alphabet do
        __map[string.sub(__alphabet, __i, __i)] = __i - 1
    end
    __data = string.gsub(__data, '%s+', '')
    local __out = {}
    local __n = 0
    local __i = 1
    while __i <= #__data do
        local __c1 = string.sub(__data, __i, __i)
        local __c2 = string.sub(__data, __i + 1, __i + 1)
        local __c3 = string.sub(__data, __i + 2, __i + 2)
        local __c4 = string.sub(__data, __i + 3, __i + 3)
        local __v1 = __map[__c1] or 0
        local __v2 = __map[__c2] or 0
        local __v3 = (__c3 ~= '=' and (__map[__c3] or 0) or 0)
        local __v4 = (__c4 ~= '=' and (__map[__c4] or 0) or 0)
        local __bits = ((__v1 << 18) | (__v2 << 12) | (__v3 << 6) | __v4)
        local __pad = 0
        if __c4 == '=' then __pad = __pad + 1 end
        if __c3 == '=' then __pad = __pad + 1 end
        if __pad == 0 then
            __n = __n + 1
            __out[__n] = string.char((__bits >> 16) & 0xFF, (__bits >> 8) & 0xFF, __bits & 0xFF)
        elseif __pad == 1 then
            __n = __n + 1
            __out[__n] = string.char((__bits >> 16) & 0xFF, (__bits >> 8) & 0xFF)
        elseif __pad == 2 then
            __n = __n + 1
            __out[__n] = string.char((__bits >> 16) & 0xFF)
        end
        __i = __i + 4
    end
    return table.concat(__out)
end

local __aerials_mk_a = "\001\120\041\110\103\024\086\007\086\100\026\005\204\022\023\106"
local __aerials_mk_b = "\028\034\048\012\061\120\163\182\050\092\201\240\035\081\224\102"
local __aerials_mk = {}
for __i = 1, 16 do
    __aerials_mk[__i] = (string.byte(__aerials_mk_a, __i) ~ string.byte(__aerials_mk_b, __i)) & 0xff
end
__aerials_mk_a = nil
__aerials_mk_b = nil
local function __aerials_derive_key(__salt)
    local __rkb = {}
    for __i = 1, 16 do
        __rkb[__i] = (__aerials_mk[__i] ~ string.byte(__salt, ((__i - 1) % 8) + 1)) & 0xff
    end
    local __key = {}
    for __wi = 0, 3 do
        local __b = __wi * 4
        __key[__wi] = (__rkb[__b + 1] | (__rkb[__b + 2] << 8) | (__rkb[__b + 3] << 16) | (__rkb[__b + 4] << 24)) & 0xffffffff
    end
    return __key
end
local function __aerials_words_from_str(__data)
    local __words = {}
    local __wi = 0
    for __i = 1, #__data, 4 do
        local __b1, __b2, __b3, __b4 = string.byte(__data, __i, __i + 3)
        __words[__wi] = (__b1 | (__b2 << 8) | (__b3 << 16) | (__b4 << 24)) & 0xffffffff
        __wi = __wi + 1
    end
    return __words
end
local function __aerials_str_from_words(__words, __n)
    local __out = {}
    for __i = 0, __n - 1 do
        local __w = __words[__i]
        __out[__i + 1] = string.char(__w & 0xff, (__w >> 8) & 0xff, (__w >> 16) & 0xff, (__w >> 24) & 0xff)
    end
    return table.concat(__out)
end
local function __aerials_xxtea_decode(__v, __n, __key)
    if __n < 2 then return end
    local __mask = 0xffffffff
    local __delta = 0x9e3779b9
    local __rounds = 6 + (52 // __n)
    local __sum = (__rounds * __delta) & __mask
    local __y = __v[0]
    local __z = 0
    local function __mx(__p, __e)
        local __k = __key[(__p & 3) ~ __e]
        local __left = (((__z >> 5) ~ ((__y << 2) & __mask)) + ((__y >> 3) ~ ((__z << 4) & __mask))) & __mask
        local __right = (((__sum ~ __y) + (__k ~ __z)) & __mask)
        return (__left ~ __right) & __mask
    end
    for __r = 1, __rounds do
        local __e = (__sum >> 2) & 3
        local __p = __n - 1
        while __p > 0 do
            __z = __v[__p - 1]
            __v[__p] = (__v[__p] - __mx(__p, __e)) & __mask
            __y = __v[__p]
            __p = __p - 1
        end
        __z = __v[__n - 1]
        __v[0] = (__v[0] - __mx(0, __e)) & __mask
        __y = __v[0]
        __sum = (__sum - __delta) & __mask
    end
end

local function __aerials_read_u16(__data, __offset)
    if (__offset + 1) > #__data then
        error('attempted to read past end of protected pack while reading uint16')
    end
    local __b1, __b2 = string.byte(__data, __offset, __offset + 1)
    return (__b1 | (__b2 << 8)), __offset + 2
end

local function __aerials_read_u32(__data, __offset)
    if (__offset + 3) > #__data then
        error('attempted to read past end of protected pack while reading uint32')
    end
    local __b1, __b2, __b3, __b4 = string.byte(__data, __offset, __offset + 3)
    return (__b1 | (__b2 << 8) | (__b3 << 16) | (__b4 << 24)), __offset + 4
end

local function __aerials_read_bytes(__data, __offset, __length)
    if __length < 0 then
        error('negative length requested from protected pack')
    end
    local __end = __offset + __length - 1
    if __end > #__data then
        error('attempted to read past end of protected pack')
    end
    return string.sub(__data, __offset, __end), __end + 1
end

local function __aerials_bytes_to_hex(__data)
    local __out = {}
    for __i = 1, #__data do
        __out[__i] = string.format('%02x', string.byte(__data, __i))
    end
    return table.concat(__out)
end

local function __aerials_decode_record(__backend_code, __meta, __cipher)
    if __backend_code == 2 then
        if #__meta ~= 8 then
            error('backend 2 record salt must be 8 bytes')
        end
        if (#__cipher % 4) ~= 0 or #__cipher < 8 then
            error('backend 2 cipher length must be a multiple of 4 and at least 8 bytes')
        end
        local __key = __aerials_derive_key(__meta)
        local __n = #__cipher // 4
        local __words = __aerials_words_from_str(__cipher)
        __aerials_xxtea_decode(__words, __n, __key)
        local __frame = __aerials_str_from_words(__words, __n)
        local __b1, __b2, __b3, __b4 = string.byte(__frame, 1, 4)
        local __orig = (__b1 | (__b2 << 8) | (__b3 << 16) | (__b4 << 24))
        if __orig < 0 or (__orig + 4) > #__frame then
            error('backend 2 frame declared length out of range')
        end
        return string.sub(__frame, 5, 4 + __orig)
    end
    error('unsupported protected pack backend code: ' .. tostring(__backend_code))
end

local __aerials_loader
local __aerials_loader_mode = 0
local __aerials_setfenv
local function __aerials_loader_check(__fn, __expected_name)
    if type(__fn) ~= 'function' then return false end
    local __dbg = rawget(_G, 'debug')
    if type(__dbg) ~= 'table' or type(__dbg.getinfo) ~= 'function' then return false end
    local __ok_info, __info = pcall(__dbg.getinfo, __fn)
    if not __ok_info or type(__info) ~= 'table' then return false end
    if __info.what ~= 'C' then return false end
    if type(__dbg.getupvalue) == 'function' then
        local __ok_up, __up_name = pcall(__dbg.getupvalue, __fn, 1)
        if __ok_up and __up_name and __up_name ~= '' then return false end
    end
    if __info.name and __info.name ~= '' and __info.name ~= __expected_name then return false end
    return true
end
do
    local __globals = _G or _ENV or {}
    local __candidate = __globals['load']
    if type(__candidate) == 'function' and __aerials_loader_check(__candidate, 'load') then
        __aerials_loader = __candidate
        __aerials_loader_mode = 1
    else
        __candidate = __globals['loadstring']
        if type(__candidate) == 'function' and __aerials_loader_check(__candidate, 'loadstring') then
            __aerials_loader = __candidate
            __aerials_loader_mode = 2
            __aerials_setfenv = __globals['setfenv']
        end
    end
end

local function __aerials_norm_path(__path)
    if type(__path) ~= 'string' then
        return nil
    end
    return string.gsub(__path, '/', '\\')
end

local __aerials_pack_bytes = __aerials_pack_b64_decode(__aerials_protected_pack_b64)
local __aerials_offset = 1
if string.sub(__aerials_pack_bytes, 1, 4) ~= 'ARPK' then
