end
local __aerials_backend_code = string.byte(__aerials_pack_bytes, __aerials_offset)
__aerials_offset = __aerials_offset + 1
local __aerials_record_count
__aerials_record_count, __aerials_offset = __aerials_read_u16(__aerials_pack_bytes, __aerials_offset)
local __aerials_entry_id_bytes
__aerials_entry_id_bytes, __aerials_offset = __aerials_read_bytes(__aerials_pack_bytes, __aerials_offset, 8)
local __aerials_entry_id = __aerials_bytes_to_hex(__aerials_entry_id_bytes)
local __aerials_index_meta_length
__aerials_index_meta_length, __aerials_offset = __aerials_read_u16(__aerials_pack_bytes, __aerials_offset)
local __aerials_index_cipher_length
__aerials_index_cipher_length, __aerials_offset = __aerials_read_u32(__aerials_pack_bytes, __aerials_offset)
local __aerials_index_meta
__aerials_index_meta, __aerials_offset = __aerials_read_bytes(__aerials_pack_bytes, __aerials_offset, __aerials_index_meta_length)
local __aerials_index_cipher
__aerials_index_cipher, __aerials_offset = __aerials_read_bytes(__aerials_pack_bytes, __aerials_offset, __aerials_index_cipher_length)
local __aerials_pack_records = {}
for __i = 1, __aerials_record_count do
    local __record_id_bytes
    __record_id_bytes, __aerials_offset = __aerials_read_bytes(__aerials_pack_bytes, __aerials_offset, 8)
    local __record_id = __aerials_bytes_to_hex(__record_id_bytes)
    local __meta_length
    __meta_length, __aerials_offset = __aerials_read_u16(__aerials_pack_bytes, __aerials_offset)
    local __cipher_length
    __cipher_length, __aerials_offset = __aerials_read_u32(__aerials_pack_bytes, __aerials_offset)
    local __meta
    __meta, __aerials_offset = __aerials_read_bytes(__aerials_pack_bytes, __aerials_offset, __meta_length)
    local __cipher
    __cipher, __aerials_offset = __aerials_read_bytes(__aerials_pack_bytes, __aerials_offset, __cipher_length)
