local __aerials_path_cache = {}
local function __aerials_resolve_record_id(__path)
    local __normalized = __aerials_norm_path(__path)
    if not __normalized then return nil, nil end
    local __lower = string.lower(__normalized)
    local __cached = __aerials_path_cache[__lower]
    if __cached then
        return __cached, __aerials_module_name_by_id[__cached]
    end
    local __direct = __aerials_module_id_by_lower[__lower]
    if __direct then
        __aerials_path_cache[__lower] = __direct
        return __direct, __aerials_module_name_by_id[__direct]
    end
    for __i = 1, #__aerials_module_order do
        local __name = __aerials_module_order[__i]
        local __name_lower = string.lower(__name)
        if string.sub(__lower, -#__name_lower) == __name_lower then
            local __id = __aerials_module_id_by_lower[__name_lower]
