local function __aerials_run_chunk(__record_id, __chunk_name)
    if type(__aerials_loader) ~= 'function' then
        error('no Lua loader available')
    end
    local __record = __aerials_pack_records[__record_id]
    if type(__record) ~= 'table' then
        error('protected pack record missing: ' .. tostring(__record_id))
    end
    local __chunk = __aerials_decode_record(__aerials_backend_code, __record.meta, __record.cipher)
    local __loader, __err
    if __aerials_loader_mode == 1 then
        __loader, __err = __aerials_loader(__chunk, __chunk_name, 'b', _ENV or _G)
    elseif __aerials_loader_mode == 2 then
        __loader, __err = __aerials_loader(__chunk, __chunk_name)
        if __loader and type(__aerials_setfenv) == 'function' then
            __aerials_setfenv(__loader, _G)
        end
    else
        error('no Lua loader available')
    end
    __chunk = nil
    pcall(collectgarbage, 'collect')
    if not __loader then
        error(__err)
    end
    local __result = __loader()
    __loader = nil
    pcall(collectgarbage, 'collect')
    return __result
