local __aerials_original_dofile = dofile
dofile = function(__path)
    local __record_id = __aerials_resolve_record_id(__path)
    if __record_id then
        return __aerials_run_chunk(__record_id, '@' .. tostring(__path))
    end
    return __aerials_original_dofile(__path)
end

if FileMgr and FileMgr.DoesFileExist then
    local __aerials_original_exists = FileMgr.DoesFileExist
    FileMgr.DoesFileExist = function(__path)
        if __aerials_resolve_record_id(__path) then
            return true
        end
        return __aerials_original_exists(__path)
    end
end

if FileMgr and FileMgr.FindFiles then
