        local __ext_norm = type(__ext) == 'string' and string.lower(__ext) or ''
        if __dir_norm and (__ext_norm == '' or __ext_norm == '.lua') then
            local __dir_lower = string.lower(__dir_norm)
            local __want_aerials = string.find(__dir_lower, 'aerialsmodules', 1, true) ~= nil
            local __want_shared = string.find(__dir_lower, 'cheraxshared', 1, true) ~= nil
            for __i = 1, #__aerials_module_order do
                local __name = __aerials_module_order[__i]
                local __name_lower = string.lower(__name)
                local __is_shared = string.sub(__name_lower, 1, 13) == 'cheraxshared\\'
                local __is_pausecore = string.sub(__name_lower, 1, 14) == 'pausemenucore\\'
                if (__want_aerials and not __is_shared and not __is_pausecore) or (__want_shared and __is_shared) then
                    local __basename = string.match(__name, '([^\\]+)$') or __name
                    local __path = __dir_norm .. '\\' .. (__is_shared and __basename or __name)
                    local __key = string.lower(__path)
                    if not __seen[__key] then
                        __result[#__result + 1] = __path
                        __seen[__key] = true
                    end
                end
            end
        end
        return __result
    end
end

return __aerials_run_chunk(__aerials_entry_id, '@main')
